// 점검 모드: true이면 유료 API 호출 0회. 실제 생성 시에만 false로 변경하세요.
const config = {
  dryRun: false,
  allowImageGeneration: false,
  textModel: 'gpt-6-luna',
  imageModel: 'gpt-image-2',
  maxCandidates: 5,
  maxOfficialSources: 2,
  maxArticleChars: 10000,
  maxOfficialChars: 2500,
  maxModelInputChars: 22000,
  maxImageGenerations: 3,
  // 추가할 때는 해당 도메인이 실제 발표 주체/연구 출처인지 확인하세요.
  officialHosts: ['openai.com','developers.openai.com','anthropic.com','www.anthropic.com',
    'blog.google','deepmind.google','ai.google','research.google','blogs.microsoft.com',
    'news.microsoft.com','microsoft.com','www.microsoft.com','ai.meta.com','about.fb.com',
    'nvidianews.nvidia.com','blogs.nvidia.com','arxiv.org','www.nature.com','nature.com',
    'science.org','www.science.org','ec.europa.eu','digital-strategy.ec.europa.eu'],
  visualStyle: {font:'Noto Sans KR',background:'#F8FAFC',foreground:'#0F172A',accent:'#2563EB',
    illustration:'Clean editorial vector illustration; navy, blue and off-white palette; no text, no logos; no documentary realism.'}
};
if (typeof config.dryRun!=='boolean' || typeof config.allowImageGeneration!=='boolean') throw new Error('모드 값은 true/false여야 합니다.');
config.maxCandidates=Math.min(5,Math.max(1,Math.trunc(config.maxCandidates)));
config.maxOfficialSources=Math.min(2,Math.max(0,Math.trunc(config.maxOfficialSources)));
config.maxImageGenerations=Math.min(3,Math.max(0,Math.trunc(config.maxImageGenerations)));
config.maxArticleChars=Math.min(10000,Math.max(500,Math.trunc(config.maxArticleChars)));
config.maxOfficialChars=Math.min(2500,Math.max(300,Math.trunc(config.maxOfficialChars)));
config.maxModelInputChars=Math.min(22000,Math.max(1000,Math.trunc(config.maxModelInputChars)));
for (const [k,v] of Object.entries(config)) if (typeof v==='number' && !Number.isFinite(v)) throw new Error('잘못된 수치 설정: '+k);
return [{json:{config,startedAt:new Date().toISOString()}}];

// Shared pure helpers. No network, secrets, dynamic code execution or external modules.
const clean = v => String(v ?? '').replace(/\s+/g, ' ').trim();
const clone = v => JSON.parse(JSON.stringify(v));
function decode(v) {
  return String(v ?? '').replace(/&#(x[0-9a-f]+|\d+);/gi, (_, n) => {
    const cp = n[0].toLowerCase() === 'x' ? parseInt(n.slice(1),16) : Number(n);
    return cp > 0 && cp <= 0x10ffff ? String.fromCodePoint(cp) : ' ';
  }).replace(/&nbsp;/gi,' ').replace(/&quot;/gi,'"').replace(/&apos;|&#39;/gi,"'")
    .replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&amp;/gi,'&');
}
function plain(v) {
  return clean(decode(String(v ?? '').replace(/<!--[\s\S]*?-->/g,' ')
    .replace(/<(script|style|noscript|nav|header|footer|aside|form|svg)\b[^>]*>[\s\S]*?<\/\1\s*>/gi,' ')
    .replace(/<[^>]*>/g,' ')));
}
function https(v, hosts) {
  const s = decode(v).trim();
  const m = /^https:\/\/([a-z0-9.-]+)(?::443)?(\/[^\s\\<>"']*)?$/i.exec(s);
  if (!m || s.length > 2000 || (hosts && !hosts.includes(m[1].toLowerCase()))) return null;
  return 'https://' + m[1].toLowerCase() + (m[2] || '/').split('#')[0];
}
function canonical(v) {
  const s = https(v, ['techcrunch.com','www.techcrunch.com']);
  if (!s) return null;
  const [base,q=''] = s.replace('https://www.techcrunch.com','https://techcrunch.com').split('?');
  const rest = q.split('&').filter(x => x && !/^(utm_[^=]*|fbclid|gclid)=/i.test(x));
  return base.replace(/\/$/,'') + (rest.length ? '?' + rest.join('&') : '');
}
function meta(html, key) {
  for (const t of html.match(/<meta\b[^>]*>/gi) || []) {
    const attrs = {};
    for (const m of t.matchAll(/([\w:-]+)\s*=\s*(["'])([\s\S]*?)\2/g)) attrs[m[1].toLowerCase()] = decode(m[3]);
    if (attrs.property === key || attrs.name === key) return attrs.content || null;
  }
  return null;
}
function extract(html, maxChars) {
  const h = String(html ?? '').slice(0, 1500000);
  if (/"isAccessibleForFree"\s*:\s*(?:false|"false")/i.test(h)) return {text:'', title:null, publishedAt:null, section:''};
  const section = /<article\b[^>]*>([\s\S]*?)<\/article\s*>/i.exec(h)?.[1]
    || /<main\b[^>]*>([\s\S]*?)<\/main\s*>/i.exec(h)?.[1] || '';
  const text = plain(section).slice(0,maxChars);
  const title = plain(meta(h,'og:title') || /<title\b[^>]*>([\s\S]*?)<\/title>/i.exec(h)?.[1] || '') || null;
  const date = meta(h,'article:published_time') || meta(h,'datePublished') || null;
  return {text, title, publishedAt:date && Number.isFinite(Date.parse(date)) ? date : null, section};
}
function officialLinks(html, hosts, max) {
  const urls = [];
  for (const m of String(html).matchAll(/<a\b[^>]*href\s*=\s*(["'])(.*?)\1/gi)) {
    const u = https(m[2], hosts);
    if (u && !/\.(pdf|zip|exe|dmg)(?:\?|$)/i.test(u) && !urls.includes(u)) urls.push(u);
  }
  return urls.slice(0,max);
}
function resultBody(raw) {
  let body = raw.body ?? raw.data ?? raw;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch {} }
  return body;
}
function successful(raw) { return !raw.error && (raw.statusCode == null || (raw.statusCode >= 200 && raw.statusCode < 300)); }
function fail(s, reason) { s.phase='stop'; s.status='failed'; s.reason=reason; return s; }
function audit(s, event, detail) { s.audit.push({event, detail}); }
function tokenUsage(s, body, task) {
  const u = body.usage || {};
  s.usage.push({task, model:body.model || s.config.textModel, requestId:body.id || null,
    inputTokens:u.input_tokens ?? null, cachedInputTokens:u.input_tokens_details?.cached_tokens ?? null,
    outputTokens:u.output_tokens ?? null, reasoningTokens:u.output_tokens_details?.reasoning_tokens ?? null,
    totalTokens:u.total_tokens ?? null});
}
function responseJSON(body) {
  if (body.status !== 'completed') throw new Error('모델 응답 미완료: ' + String(body.status || 'unknown'));
  const parts = (body.output || []).filter(x => x.type==='message').flatMap(x => x.content || []);
  if (parts.some(x => x.type==='refusal')) throw new Error('모델이 응답을 거절했습니다.');
  const texts = parts.filter(x => x.type==='output_text');
  if (texts.length !== 1) throw new Error('단일 구조화 응답이 아닙니다.');
  const d = typeof texts[0].text === 'string' ? JSON.parse(texts[0].text) : texts[0].text;
  if (!d || typeof d !== 'object' || Array.isArray(d)) throw new Error('JSON 객체가 아닙니다.');
  return d;
}
function parseVisualData(slide) {
  const v = slide.visual;
  if (['text','photo','illustration'].includes(v.type)) {
    if (v.dataJson !== null) throw new Error('이미지/텍스트 장의 dataJson은 null이어야 합니다.');
    return null;
  }
  let data;
  try { data=parseVisualJson(v.dataJson); } catch { throw new Error('시각 자료 데이터 JSON 오류'); }
  if (!data || typeof data!=='object' || Array.isArray(data)) throw new Error('시각 자료 데이터 객체 오류');
  if (v.type==='comparison' && (!Array.isArray(data.columns) || data.columns.length<2 || data.columns.length>5
      || !data.columns.every(x=>typeof x==='string') || !Array.isArray(data.rows) || !data.rows.length || data.rows.length>8
      || data.rows.some(r=>!Array.isArray(r)||r.length!==data.columns.length||r.some(x=>typeof x!=='string')))) throw new Error('비교표 형식 오류');
  if (v.type==='diagram') {
    if (!Array.isArray(data.nodes)||!data.nodes.length||data.nodes.length>10||!Array.isArray(data.edges)||data.edges.length>15
      ||data.nodes.some(x=>!clean(x.id)||!clean(x.label))||new Set(data.nodes.map(x=>x.id)).size!==data.nodes.length
      ||data.edges.some(e=>!data.nodes.some(n=>n.id===e.from)||!data.nodes.some(n=>n.id===e.to))) throw new Error('흐름도 형식 오류');
  }
  if (v.type==='chart' && (!['bar','line'].includes(data.chartType)||!clean(data.unit)||!Array.isArray(data.points)
    ||!data.points.length||data.points.length>10||data.points.some(p=>!clean(p.label)||typeof p.value!=='number'||!Number.isFinite(p.value)))) throw new Error('차트 형식 오류');
  return data;
}
// BEGIN NORMALIZED EVIDENCE HELPERS
function draftLimits() {
  return {evidence:200, minSlides:3, maxSlides:7, maxAssets:5,
    title:200, summary:5000, slideTitle:120, slideContent:1200, description:500, plan:1000};
}
function applyDraftLimits(schema) {
  const s=JSON.parse(JSON.stringify(schema)),l=draftLimits(),p=s.properties;
  p.title.maxLength=l.title;p.summary.maxLength=l.summary;
  for(const key of ['coreMessage','readerNeeds','sequenceReason'])p.plan.properties[key].maxLength=l.plan;
  // An empty slides/evidence array is valid for status=skip; ready is checked at runtime.
  p.slides.minItems=0;p.slides.maxItems=l.maxSlides;
  const slide=p.slides.items.properties;
  slide.sequence.minimum=1;slide.sequence.maximum=l.maxSlides;
  slide.title.maxLength=l.slideTitle;slide.content.maxLength=l.slideContent;
  slide.visual.properties.description.maxLength=l.description;
  slide.visual.properties.assetKey.pattern='^[a-z][a-z0-9_]{0,39}$';
  slide.visual.properties.searchQuery.maxLength=180;
  slide.visual.properties.generationPrompt.maxLength=1200;
  return s;
}
function assertEvidence(quotes, docs, allowedIds, context) {
  const clean=v=>String(v??'').replace(/\s+/g,' ').trim();
  if(!Array.isArray(quotes)||!quotes.length)throw new Error(context+': 근거 배열이 비어 있습니다.');
  if(quotes.length>draftLimits().evidence)throw new Error(context+': 근거 개수 상한 초과 ('+quotes.length+').');
  for(const [index,q]of quotes.entries()){
    const doc=docs.find(d=>d.id===q?.sourceId);
    if(!doc)throw new Error(context+': 존재하지 않는 출처 ID ('+String(q?.sourceId)+').');
    if(allowedIds&&!allowedIds.includes(q.sourceId))throw new Error(context+': 슬라이드 출처 목록에 없는 근거 ('+q.sourceId+').');
    if(clean(q.quote).length<12)throw new Error(context+': 근거 '+(index+1)+'의 인용문이 너무 짧습니다.');
    if(!clean(doc.title+' '+doc.text).includes(clean(q.quote)))
      throw new Error(context+': 근거 '+(index+1)+'의 인용문이 원문과 다릅니다.');
  }
}
function numericValues(input) {
  const words = { zero: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6,
    seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12, thirteen: 13,
    fourteen: 14, fifteen: 15, sixteen: 16, seventeen: 17, eighteen: 18, nineteen: 19,
    twenty: 20, thirty: 30, forty: 40, fifty: 50, sixty: 60, seventy: 70, eighty: 80, ninety: 90 };
  const months = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august',
    'september', 'october', 'november', 'december'];
  let text = String(input ?? '').replace(/\b(January|February|March|April|May|June|July|August|September|October|November|December)\b/g,
    word => `${months.indexOf(word.toLowerCase()) + 1}월`);
  // An indefinite article expresses one only before a measurement/scale unit.
  // Do not turn articles in ordinary prose ("a platform", "a few years") into evidence for 1.
  const measuredUnit = '(?:year|month|week|day|hour|minute|second|decade|century|hundred|thousand|million|billion|trillion)';
  text = text.replace(new RegExp(`\\bhalf (?:a|an) (?=${measuredUnit}\\b)`, 'gi'), '0.5 ')
    .replace(new RegExp(`\\b(?:a|an) (?=${measuredUnit}\\b)`, 'gi'), '1 ');
  const wordPattern = new RegExp(`\\b(${Object.keys(words).join('|')})(?:[- ](one|two|three|four|five|six|seven|eight|nine))?\\b`, 'gi');
  text = text.replace(wordPattern, (_, first, second) => {
    const value = words[first.toLowerCase()];
    return second && value >= 20 ? String(value + words[second.toLowerCase()])
      : second ? `${value} ${words[second.toLowerCase()]}` : String(value);
  });
  const scales = { hundred: 100, thousand: 1000, million: 1e6, billion: 1e9, trillion: 1e12,
    '십': 10, '백': 100, '천': 1000, '만': 1e4, '억': 1e8, '조': 1e12 };
  const number = String.raw`\d+(?:,\d{3})*(?:\.\d+)?`;
  const scale = String.raw`(?:hundred|thousand|million|billion|trillion)\b|[십백천만억조]`;
  const quantity = new RegExp(`${number}(?:\\s*(?:${scale})(?:\\s*${number})?)*`, 'gi');
  return [...text.matchAll(quantity)].map(match => {
    const parts = match[0].replace(/,/g, '').match(/\d+(?:\.\d+)?|hundred|thousand|million|billion|trillion|[십백천만억조]/gi);
    let total = 0, group = 0, pending = null;
    for (const part of parts) {
      const multiplier = scales[part.toLowerCase()];
      if (!multiplier) { pending = Number(part); continue; }
      if (multiplier < 10000) { group += (pending ?? 1) * multiplier; pending = null; }
      else { total += (group + (pending ?? 0) || 1) * multiplier; group = 0; pending = null; }
    }
    return String(total + group + (pending ?? 0));
  });
}
function assertSupportedNumbers(text, evidence, context) {
  const supported = new Set(numericValues(evidence));
  const missing = [...new Set(numericValues(text).filter(value => !supported.has(value)))];
  if (missing.length) throw new Error(`${context}: 인용 근거에 없는 수치가 있습니다 (${missing.join(', ')}).`);
}
function parseVisualJson(raw) {
  try { return JSON.parse(raw); }
  catch {
    // Some model responses encode the JSON object's quotes twice. Decode one
    // JSON string layer only; the caller still validates the complete schema.
    if (typeof raw !== 'string' || !/^\s*\{\\"/.test(raw)) throw new Error('시각 자료 데이터 JSON 오류');
    try { return JSON.parse(JSON.parse('"' + raw + '"')); }
    catch { throw new Error('시각 자료 데이터 JSON 오류'); }
  }
}
function normalizeImagePlan(visual, sequence) {
  const invalid = field => { throw new Error(`슬라이드 ${sequence} 이미지 계획: ${field} 오류`); };
  if (typeof visual.assetKey !== 'string' || !/^[a-z][a-z0-9_-]{0,39}$/.test(visual.assetKey)) invalid('assetKey (영문 소문자로 시작하는 1~40자)');
  if (visual.searchQuery != null && typeof visual.searchQuery !== 'string') invalid('searchQuery (문자열 또는 null)');
  let query = visual.searchQuery?.trim();
  if (!query) query = visual.assetKey.replace(/[_-]+/g, ' ').trim();
  if (query.length > 180) invalid('searchQuery (최대 180자)');
  if (typeof visual.generationPrompt !== 'string' || !visual.generationPrompt.trim()
      || visual.generationPrompt.length > 1200) invalid('generationPrompt (1~1200자)');
  visual.searchQuery = query;
  return visual;
}
function koreanPattern(allowEmpty = false) {
  const text = '[^ぁ-ヿ]*[가-힣][^ぁ-ヿ]*';
  return allowEmpty ? '^(?:|' + text + ')$' : '^' + text + '$';
}
function koreanDraftSchema(schema) {
  const next = JSON.parse(JSON.stringify(schema));
  const korean = (field, empty = false) => ({...field, pattern:koreanPattern(empty),
    description:'Write natural Korean (ko-KR) with Hangul. Do not write Japanese or mix Japanese sentences into Korean. Keep Latin product names when needed.'
      + (empty ? ' An empty string is allowed only for unused fields when status is skip, or reason when status is ready.' : '')});
  for(const key of ['title','summary','reason'])next.properties[key]=korean(next.properties[key],true);
  for(const key of ['coreMessage','readerNeeds','sequenceReason'])
    next.properties.plan.properties[key]=korean(next.properties.plan.properties[key],true);
  const slide=next.properties.slides.items.properties;
  for(const key of ['title','content'])slide[key]=korean(slide[key]);
  slide.visual.properties.description=korean(slide.visual.properties.description);
  return next;
}
function assertKoreanText(value, field) {
  if(typeof value!=='string' || !new RegExp(koreanPattern()).test(value))
    throw new Error(field+'의 한국어 형식 오류: 한글 문장이 필요하며 일본어 문장을 섞을 수 없습니다.');
}
function validateKoreanDraft(draft) {
  if(draft.status==='skip'){assertKoreanText(draft.reason,'건너뛰기 사유');return;}
  assertKoreanText(draft.title,'제목');assertKoreanText(draft.summary,'요약');
  for(const key of ['coreMessage','readerNeeds','sequenceReason'])assertKoreanText(draft.plan?.[key],'구성 계획 '+key);
  for(const slide of draft.slides || []){
    assertKoreanText(slide.title,'슬라이드 '+slide.sequence+' 제목');
    assertKoreanText(slide.content,'슬라이드 '+slide.sequence+' 본문');
    assertKoreanText(slide.visual?.description,'슬라이드 '+slide.sequence+' 시각 설명');
  }
}
function evidenceCatalog(docs) {
  const catalog = [];
  for (const doc of docs) {
    const pieces = [doc.title, ...String(doc.text ?? '').split(/(?<=[.!?])\s+(?=[A-Z“"‘])/u)];
    for (const text of pieces) {
      const quote = String(text ?? '').trim();
      if (quote.length < 12) continue;
      catalog.push({ id: `${doc.id}:q${catalog.length + 1}`, sourceId: doc.id, quote });
      if (catalog.length >= draftLimits().evidence) return catalog;
    }
  }
  return catalog;
}
function resolveEvidence(draft, catalog = []) {
  const byId = new Map(catalog.map(q => [q.id, q]));
  const resolve = (refs, label) => {
    if (!Array.isArray(refs)) throw new Error(`${label}: 근거 배열이 필요합니다.`);
    return refs.map(ref => {
      // Historical responses retain their strict literal-quote checks.
      if (ref && typeof ref === 'object' && !Array.isArray(ref)) return ref;
      const source = typeof ref === 'string' ? byId.get(ref) : null;
      if (!source) throw new Error(`${label}: 원문에 없는 근거 ID ${String(ref).slice(0, 80)}`);
      return { sourceId: source.sourceId, quote: source.quote };
    });
  };
  draft.evidence = resolve(draft.evidence, '제목/요약');
  for (const slide of draft.slides ?? []) slide.evidence = resolve(slide.evidence, `슬라이드 ${slide.sequence}`);
  return draft;
}
function evidenceRequest(state, schema) {
  const catalog = evidenceCatalog(state.docs);
  if (!catalog.length) throw new Error('근거 문장이 없습니다.');
  state.evidenceCatalog = catalog;
  const next = applyDraftLimits(koreanDraftSchema(schema));
  const refs = { type: 'array', minItems:0, maxItems:draftLimits().evidence, items: { type: 'string', enum: catalog.map(q => q.id) } };
  next.properties.evidence = refs;
  next.properties.slides.items.properties.evidence = JSON.parse(JSON.stringify(refs));
  next.properties.slides.items.properties.evidence.minItems=1;
  if (next.properties.slides.items.properties.sourceIds)
    next.properties.slides.items.properties.sourceIds.items = { type: 'string', enum: state.docs.map(d => d.id) };
  return { schema: next, sources: state.docs.map(({text, ...doc}) => ({ ...doc,
    evidence: catalog.filter(q => q.sourceId === doc.id).map(({id, quote}) => ({id, quote})) })) };
}
// END NORMALIZED EVIDENCE HELPERS
function validateDraft(d, s) {
  validateKoreanDraft(d);
  resolveEvidence(d, s.evidenceCatalog);
  if (d.status==='skip') { if (!clean(d.reason)) throw new Error('skip 사유 누락'); return null; }
  if (d.status!=='ready' || !clean(d.title) || !clean(d.summary) || !d.plan || !clean(d.plan.coreMessage)
    || !clean(d.plan.readerNeeds) || !clean(d.plan.sequenceReason)) throw new Error('초안/구성 계획 누락');
  if (!/[가-힣]/.test(d.title) || !/[가-힣]/.test(d.summary)) throw new Error('제목 또는 요약의 한국어 누락');
  assertEvidence(d.evidence,s.docs,null,'제목/요약');
  if (!Array.isArray(d.slides)||d.slides.length<draftLimits().minSlides||d.slides.length>draftLimits().maxSlides) throw new Error('슬라이드는 3~7장이어야 합니다.');
  if(d.title.length>draftLimits().title||d.summary.length>draftLimits().summary)throw new Error('제목/요약 길이 상한 초과');
  if(Object.values(d.plan).some(v=>typeof v!=='string'||v.length>draftLimits().plan))throw new Error('구성 계획 길이 상한 초과');
  const assets = new Map();
  d.slides.forEach((x,i)=>{
    if (x.sequence!==i+1||!/[가-힣]/.test(x.title)||!/[가-힣]/.test(x.content)||x.title.length>draftLimits().slideTitle||x.content.length>draftLimits().slideContent)
      throw new Error('슬라이드 번호/한국어/분량 오류');
    if (!Array.isArray(x.sourceIds)||!x.sourceIds.length||x.sourceIds.some(id=>!s.docs.some(d=>d.id===id))
      ) throw new Error('슬라이드 '+x.sequence+': 출처 ID 오류');
    assertEvidence(x.evidence,s.docs,x.sourceIds,'슬라이드 '+x.sequence);
    if (!x.visual || !['photo','illustration','comparison','diagram','chart','text'].includes(x.visual.type)
      || !clean(x.visual.description)) throw new Error('시각 자료 계획 오류');
    if(x.visual.description.length>draftLimits().description)throw new Error('슬라이드 '+x.sequence+': 시각 설명 길이 상한 초과');
    x.visual.data=parseVisualData(x);
    const semanticData = x.visual.type==='diagram' ? x.visual.data.nodes.map(n=>n.label).join(' ')
      : x.visual.type==='chart' ? x.visual.data.points.map(p=>p.label+' '+p.value+' '+x.visual.data.unit).join(' ')
      : x.visual.data ? JSON.stringify(x.visual.data) : '';
